            <i class="fas fa-suitcase-rolling me-3"></i>Travel Packages
          </h1>
          <p class="text-muted mb-0">Discover amazing destinations and experiences</p>
        </div>
        <div *ngIf="isAuthenticated">
          <a routerLink="/add-trip" class="btn btn-success btn-lg">
            <i class="fas fa-plus me-2"></i>Add New Trip
          </a>
        </div>
      </div>
    </div>
  </div>

  <!-- Statistics Cards -->
  <div class="row mb-4" *ngIf="!loading && trips.length > 0">
    <div class="col-md-3 col-sm-6 mb-3">
      <div class="card bg-primary text-white h-100">
        <div class="card-body text-center">
          <i class="fas fa-map-marked-alt fa-2x mb-2"></i>
          <h3 class="card-title">{{ getTripStats().total }}</h3>
          <p class="card-text">Total Trips</p>
        </div>
      </div>
    </div>
    <div class="col-md-3 col-sm-6 mb-3">
      <div class="card bg-success text-white h-100">
        <div class="card-body text-center">
          <i class="fas fa-calendar-alt fa-2x mb-2"></i>
          <h3 class="card-title">{{ getTripStats().averageDuration }}</h3>
          <p class="card-text">Avg. Days</p>
        </div>
      </div>
    </div>
    <div class="col-md-3 col-sm-6 mb-3">
      <div class="card bg-info text-white h-100">
        <div class="card-body text-center">
          <i class="fas fa-dollar-sign fa-2x mb-2"></i>
          <h3 class="card-title">{{ formatPrice(getTripStats().priceRange.min) }}</h3>
          <p class="card-text">From Price</p>
        </div>
      </div>
    </div>
    <div class="col-md-3 col-sm-6 mb-3">
      <div class="card bg-warning text-white h-100">
        <div class="card-body text-center">
          <i class="fas fa-star fa-2x mb-2"></i>
          <h3 class="card-title">{{ formatPrice(getTripStats().priceRange.max) }}</h3>
          <p class="card-text">Top Price</p>
        </div>
      </div>
    </div>
  </div>

  <!-- Loading State -->
  <div *ngIf="loading" class="text-center py-5">
    <div class="spinner-border text-primary" role="status" style="width: 3rem; height: 3rem;">
      <span class="visually-hidden">Loading...</span>
    </div>
    <p class="mt-3 text-muted">Loading travel packages...</p>
  </div>

  <!-- Error State -->
  <div *ngIf="error" class="alert alert-danger" role="alert">
    <i class="fas fa-exclamation-triangle me-2"></i>{{ error }}
    <button type="button" class="btn btn-outline-danger ms-3" (click)="loadTrips()">
      <i class="fas fa-redo me-1"></i>Retry
    </button>
  </div>

  <!-- Empty State -->
  <div *ngIf="!loading && !error && trips.length === 0" class="text-center py-5">
    <div class="empty-state">
      <i class="fas fa-suitcase fa-4x text-muted mb-3"></i>
      <h3 class="text-muted">No trips available</h3>
      <p class="text-muted">There are currently no travel packages to display.</p>
      <a *ngIf="isAuthenticated" routerLink="/add-trip" class="btn btn-primary">
        <i class="fas fa-plus me-2"></i>Add First Trip
      </a>
    </div>
  </div>

  <!-- Trip Cards Grid -->
  <div *ngIf="!loading && !error && trips.length > 0" class="row">
    <div class="col-lg-4 col-md-6 mb-4" *ngFor="let trip of trips; trackBy: trackByTripId">
      <app-trip-card 
        [trip]="trip"
        [showAdminActions]="isAuthenticated"
        (deleteTrip)="onTripDeleted($event)">
      </app-trip-card>
    </div>
  </div>

  <!-- Load More Button (if needed in future) -->
  <div *ngIf="!loading && !error && trips.length > 0" class="text-center mt-4">
    <p class="text-muted">
      <i class="fas fa-check-circle me-1"></i>
      Showing all {{ trips.length }} travel packages
    </p>
  </div>
</div>
